// ---------------------------------------------------------------------------
// The scenario and what the path uses, derived from game-data
// ---------------------------------------------------------------------------

const SCENARIO = THE_FIRST_HIRE_SCENARIO;
const setup = { scenario: SCENARIO } as const;

/** Cases in the path's batch and its sale. */
const PATH_CASES = 1;

const HOME: LocationId = SCENARIO.founderStartLocationId;

const HOME_FACILITY = (() => {
  const f = SCENARIO.facilities.find((sf) => FACILITIES.find((d) => d.id === sf.id)?.locationId === HOME);
  if (!f) throw new Error(`Scenario: no facility at the start location ${HOME}`);
  return f;
})();

const RECIPE = (() => {
  const r = RECIPES.find((x) => x.id === BASIC_MOONSHINE_RECIPE);
  if (!r) throw new Error("game-data: no basic moonshine recipe");
  return r;
})();

const SUPPLIER = (() => {
  const s = SUPPLIERS.find(
    (d) => SCENARIO.supplierIds.includes(d.id) && RECIPE.inputsPerCase.every((i) => d.stock.some((st) => st.materialId === i.materialId)),
  );
  if (!s) throw new Error("Scenario: no supplier stocks every input of basic moonshine");
  return s;
})();

const TRUCK = (() => {
  const v = SCENARIO.vehicleIds[0];
  if (!v) throw new Error("Scenario: no vehicle");
  return v;
})();

const routeById = (id: RouteId) => {
  const r = ROUTES.find((x) => x.id === id);
  if (!r) throw new Error(`no route ${id}`);
  return r;
};

/** The first scenario buyer (in scenario order) that wants basic moonshine, with a direct risk-free route out from home. */
const SALE = (() => {
  for (const buyerId of SCENARIO.buyerIds) {
    const buyer = BUYERS.find((b) => b.id === buyerId);
    if (!buyer) continue;
    const route = ROUTES.find((r) => r.fromLocationId === HOME && r.toLocationId === buyer.locationId && r.riskPpm === 0);
    if (route) return { buyerId: buyer.id as BuyerId, locationId: buyer.locationId, route };
  }
  throw new Error("Scenario: no buyer reachable from home by a direct risk-free route");
})();

const PPM = 1_000_000;
/** `value × ppm / 1 000 000`, rounded up, in integers. */
const scaleUp = (value: number, ppm: number): number => Math.floor((value * ppm + PPM - 1) / PPM);
const tired = (duration: number): number => scaleUp(duration, TIRED_DURATION_PPM);
const footTicks = (routeDuration: number): number => scaleUp(routeDuration, FOOT_TRAVEL_PPM);

/** How long an activity keeps the founder busy when it applies at `applyTick` (ADR 0023 decisions 4, 7). */
function activityTicks(kind: ActivityKind, state: GameState, applyTick: number): number {
  const base = ACTIVITY_DURATIONS[kind];
  return applyTick - state.founder.awakeSince > TIRED_AFTER_TICKS ? tired(base) : base;
}

/** The one-click "rest until morning" for a command applying at `applyTick` (decision 7, paused: exact). */
function oneClickRestUntil(applyTick: number): Tick {
  const earliest = applyTick + MIN_REST_TICKS;
  const latest = applyTick + MAX_REST_TICKS;
  let next = earliest - minuteOfDay(tick(earliest)) + WAKE_HOUR * TICKS_PER_HOUR;
  if (next < earliest) next += TICKS_PER_DAY;
  return tick(Math.min(Math.max(next, earliest), latest));
}

function isOpen(locationId: LocationId, t: number): boolean {
  const entry = PLACE_HOURS.find((h) => h.locationId === locationId);
  if (!entry) return true;
  const m = minuteOfDay(tick(t));
  return entry.intervals.some(({ opensAtMinute: o, closesAtMinute: c }) => (o < c ? m >= o && m < c : m >= o || m < c));
}

const isFree = (s: GameState): boolean => s.founder.whereabouts.kind === "PRESENT" && s.founder.whereabouts.busy === null;
const truckOf = (s: GameState) => {
  const v = s.vehicles.find((x) => x.id === TRUCK);
  if (!v) throw new Error(`no truck ${TRUCK}`);
  return v;
};
const homeCases = (s: GameState): number =>
  s.productPools.filter((p) => p.facilityId === HOME_FACILITY.id && p.productId === RECIPE.productId && p.quality === RECIPE.quality).reduce((n, p) => n + p.quantity, 0);

function expectApplied(result: CommandResult, what: string): asserts result is Extract<CommandResult, { status: "applied" }> {
  if (result.status !== "applied") throw new Error(`${what}: expected applied, got ${JSON.stringify(result)}`);
}

// ---------------------------------------------------------------------------
// The ledger reconciles (as fin-001.locked.test.ts and sprint-zero check it)
// ---------------------------------------------------------------------------

const prepaidByJobs = (state: GameState): number => state.productionJobs.reduce((n, j) => n + (j.conversionPrepaid ?? 0), 0);

function expectLedgerReconciles(state: GameState, where: string): void {
  const keys = new Set<string>();
  for (const t of state.ledger.transactions) {
    expect(keys.has(t.idempotencyKey), `${where}: duplicate key ${t.idempotencyKey}`).toBe(false);
    keys.add(t.idempotencyKey);
    expect(t.entries.length, `${where}: ${t.id} (${t.kind}) has one line`).not.toBe(1);
    for (const e of t.entries) expect(e.amount, `${where}: ${t.id} ${e.account}`).toBeGreaterThan(0);
    const { debits, credits } = entryTotals(t.entries);
    expect(debits, `${where}: ${t.id} (${t.kind}) balances`).toBe(credits);
  }
  const last = state.ledger.transactions.at(-1);
  if (last) expect(checkInvariants(state, last), `${where}: invariants`).toEqual([]);
  const sheet = balanceSheet(state);
  expect(sheet.assets, `${where}: assets = liabilities + equity`).toBe(sheet.liabilities + sheet.equity + sheet.netIncome);
  const balances = accountBalances(state.ledger.transactions);
  expect(balances.CASH, `${where}: cash`).toBeGreaterThanOrEqual(0);
  expect(balances.PRODUCTION_IN_PROGRESS, `${where}: prepaid conversion`).toBe(prepaidByJobs(state));
}

// ---------------------------------------------------------------------------
// No traps: decision 8's B and the REST experiment (copied from no-trap.locked.test.ts)
// ---------------------------------------------------------------------------

/** The longest simple path (no location twice, decision 3) by the given leg duration, over every route in either direction. */
function longestSimplePath(legTicks: (routeDuration: number) => number): number {
  let best = 0;
  const walk = (at: LocationId, visited: Set<string>, ticks: number): void => {
    if (ticks > best) best = ticks;
    for (const r of ROUTES) {
      for (const reversed of [false, true]) {
        const from = reversed ? r.toLocationId : r.fromLocationId;
        const to = reversed ? r.fromLocationId : r.toLocationId;
        if (from !== at || visited.has(to)) continue;
        visited.add(to);
        walk(to, visited, ticks + legTicks(r.durationTicks));
        visited.delete(to);
      }
    }
  };
  for (const l of LOCATIONS) walk(l.id, new Set([l.id]), 0);
  return best;
}

const LONGEST_ACTIVITY = Math.max(...Object.values(ACTIVITY_DURATIONS));
const LONGEST_ROUTE = Math.max(...ROUTES.map((r) => r.durationTicks));
const LONGEST_DELAY = Math.max(0, ...ROUTES.filter((r) => r.riskPpm > 0).map((r) => r.delayTicks));

/** Decision 8's B, from game-data. */
const B = Math.max(
  tired(LONGEST_ACTIVITY),
  MAX_REST_TICKS,
  2 * LONGEST_ROUTE + LONGEST_DELAY + tired(ACTIVITY_DURATIONS.LOAD_TRUCK),
  longestSimplePath(footTicks),
  longestSimplePath((d) => d),
);

/** The one-click REST each tick until accepted; checks decision 8 item 1 at each step and the bound at the end. */
function expectRestWithinBound(sim: KernelSimulation, where: string): void {
  const now = sim.state.tick + 1;
  const queued = sim.state.queuedCommands.filter((e) => e.issuer.kind === "FOUNDER").map((e) => e.scheduledTick as number);
  const bound = Math.max(now, ...queued) + B + 1;
  for (;;) {
    const before = sim.state;
    const applyTick = before.tick + 1;
    if (applyTick > bound) throw new Error(`${where}: trapped, REST still refused at apply tick ${applyTick} > bound ${bound} (B ${B}); founder ${JSON.stringify(before.founder)}`);
    const untilTick = oneClickRestUntil(applyTick);
    const result = sim.dispatch({ command: { type: "REST", untilTick } });
    const dueNow = before.queuedCommands.some((e) => e.scheduledTick === applyTick);
    if (result.status === "applied") {
      const w = before.founder.whereabouts;
      expect(w.kind === "PRESENT" || (w.kind === "RESTING" && dueNow), `${where}: REST accepted only at a place`).toBe(true);
      const locationId = w.kind === "PRESENT" || w.kind === "RESTING" ? w.locationId : null;
      expect(sim.state.founder.whereabouts, `${where}: resting where they were`).toEqual({ kind: "RESTING", locationId, startedAt: applyTick, until: untilTick });
      return;
    }
    if (result.status !== "rejected") throw new Error(`${where}: REST neither applied nor rejected: ${JSON.stringify(result)}`);
    expect(["FOUNDER_AWAY", "FOUNDER_BUSY"], `${where}: REST refused only for being away or busy`).toContain(result.reason.code);
    if (isFree(before) && !dueNow) throw new Error(`${where}: REST refused for a free founder at apply tick ${applyTick}: ${JSON.stringify(result.reason)}`);
    sim.advance(1);
  }
}

// ---------------------------------------------------------------------------
// Static non-leak: the renaming canonicaliser, the live view and the
// perturbation (copied from knowledge/non-leak.locked.test.ts)
// ---------------------------------------------------------------------------

const PREFIXES: readonly string[] = Object.values(DYNAMIC_ID_PREFIXES);
const DYNAMIC_ID_TOKEN = new RegExp(`(?<![a-z0-9-])(${PREFIXES.join("|")})-(0|[1-9][0-9]*)(?![a-z0-9-])`, "g");

function renameDynamicIds(json: string): string {
  const names = new Map<string, string>();
  const counts = new Map<string, number>();
  return json.replace(DYNAMIC_ID_TOKEN, (token: string, prefix: string) => {
    let name = names.get(token);
    if (name === undefined) {
      const k = (counts.get(prefix) ?? 0) + 1;
      counts.set(prefix, k);
      name = `${prefix}#${k}`;
      names.set(token, name);
    }
    return name;
  });
}

const canonical = (value: unknown): string => renameDynamicIds(canonicalJson(value));
const canonicalTree = (value: unknown): unknown => JSON.parse(canonical(value)) as unknown;

function expectSamePlayerView(actual: PlayerSnapshot, expected: PlayerSnapshot, what: string): void {
  const a = canonical(actual);
  const b = canonical(expected);
  if (a !== b) {
    for (const key of Object.keys(expected) as (keyof PlayerSnapshot)[]) {
      expect(canonicalTree(actual[key]), `${what}: player snapshot section \`${key}\` differs (a leak)`).toEqual(canonicalTree(expected[key]));
    }
    expect(JSON.parse(a), `${what}: player snapshots differ (a leak)`).toEqual(JSON.parse(b));
  }
}

const buyerLocation = (id: BuyerId): LocationId => BUYERS.find((b) => b.id === id)!.locationId;
const facilityLocation = (id: string): LocationId | null => FACILITIES.find((f) => f.id === id)?.locationId ?? null;
const supplierLocation = (id: string): LocationId | null => SUPPLIERS.find((s) => s.id === id)?.locationId ?? null;
const isPartyLocation = (l: LocationId): boolean => BUYERS.some((b) => b.locationId === l) || SUPPLIERS.some((s) => s.locationId === l);

interface ViewScope {
  readonly observed: LocationId | null;
  readonly partyVisible: boolean;
  readonly liveRoutes: ReadonlySet<RouteId>;
}

function viewScope(s: GameState): ViewScope {
  const w = s.founder.whereabouts;
  const liveRoutes = new Set<RouteId>();
  let observed: LocationId | null = null;
  let partyVisible = true;
  if (w.kind === "PRESENT") {
    observed = w.locationId;
    partyVisible = isOpen(w.locationId, s.tick) || isOpen(w.locationId, s.tick + 1);
  } else if (w.kind === "ON_DELIVERY") {
    if (w.atStop !== null && w.atStop.tick === s.tick) observed = w.atStop.locationId;
    const delivery = s.deliveries.find((d) => d.id === w.deliveryId);
    if (delivery) liveRoutes.add(delivery.routeId);
    const vehicle = s.vehicles.find((v) => v.id === w.vehicleId);
    if (vehicle?.trip) liveRoutes.add(vehicle.trip.routeId);
  } else if (w.kind === "TRAVELLING") {
    const leg = w.path[w.legIndex];
    if (leg) liveRoutes.add(leg.routeId);
  }
  if (observed !== null) for (const id of LIVE_VIEW_ROUTES.find((e) => e.locationId === observed)?.routeIds ?? []) liveRoutes.add(id);
  return { observed, partyVisible, liveRoutes };
}

function hiddenPredicates(s: GameState) {
  const v = viewScope(s);
  const partyHidden = (location: LocationId | null): boolean => location !== v.observed || !v.partyVisible;
  return {
    facility: (id: string): boolean => facilityLocation(id) !== v.observed,
    buyer: (id: BuyerId): boolean => partyHidden(buyerLocation(id)),
    supplier: (id: string): boolean => partyHidden(supplierLocation(id)),
    market: v.observed === null || !isPartyLocation(v.observed) || !v.partyVisible,
    standing: v.observed === null || (isPartyLocation(v.observed) && !v.partyVisible),
    route: (id: RouteId): boolean => !v.liveRoutes.has(id),
  };
}

interface IdMap {
  readonly mul: number;
  readonly add: number;
}

/** Renumbers every dynamic ID with `n ↦ mul·n + add` per prefix (order-preserving); counters move past every ID. */
function renumberIds(state: GameState, maps: Readonly<Record<string, IdMap>>): GameState {
  const json = JSON.stringify(state).replace(DYNAMIC_ID_TOKEN, (_token: string, prefix: string, digits: string) => {
    const m = maps[prefix] ?? { mul: 1, add: 0 };
    return `${prefix}-${m.mul * Number(digits) + m.add}`;
  });
  const renamed = JSON.parse(json) as GameState;
  const nextId = { ...renamed.counters.nextId };
  for (const kind of DYNAMIC_ID_KINDS) {
    const m = maps[DYNAMIC_ID_PREFIXES[kind]] ?? { mul: 1, add: 0 };
    nextId[kind] = m.mul * nextId[kind] + m.add + 1;
  }
  return { ...renamed, counters: { ...renamed.counters, nextId } };
}

interface HiddenPlan {
  readonly ids: Readonly<Record<string, IdMap>>;
  readonly rngSeeds: readonly number[];
  readonly journalKeep: number;
  readonly sequenceBump: number;
  readonly budget: number;
  readonly demand: number;
  readonly wantPriceDelta: number;
  readonly dropOffers: boolean;
  readonly offerPriceDelta: number;
  readonly supplierAvailable: number;
  readonly supplierPriceDelta: number;
  readonly marketDelta: { readonly demand: number; readonly supply: number; readonly spot: number };
  readonly flipRoutes: readonly boolean[];
  readonly jobDelay: number;
  readonly extraStock: number;
  readonly reputation: number;
  readonly futureClosure: { readonly offset: number; readonly routePick: number; readonly durationTicks: number } | null;
}

const idMapArb: fc.Arbitrary<IdMap> = fc.record({ mul: fc.integer({ min: 1, max: 3 }), add: fc.integer({ min: 0, max: 60 }) });

const hiddenPlanArb: fc.Arbitrary<HiddenPlan> = fc.record({
  ids: fc.record(Object.fromEntries(PREFIXES.map((p) => [p, idMapArb])) as Record<string, fc.Arbitrary<IdMap>>),
  rngSeeds: fc.array(fc.integer({ min: 1, max: 2_000_000_000 }), { minLength: RNG_STREAMS.length, maxLength: RNG_STREAMS.length }),
  journalKeep: fc.nat(),
  sequenceBump: fc.integer({ min: 0, max: 50 }),
  budget: fc.oneof(fc.constant(0), fc.integer({ min: 0, max: 500_000 })),
  demand: fc.integer({ min: 0, max: 40 }),
  wantPriceDelta: fc.integer({ min: -500, max: 500 }),
  dropOffers: fc.boolean(),
  offerPriceDelta: fc.integer({ min: -500, max: 500 }),
  supplierAvailable: fc.integer({ min: 0, max: 200 }),
  supplierPriceDelta: fc.integer({ min: -200, max: 200 }),
  marketDelta: fc.record({ demand: fc.integer({ min: -50, max: 50 }), supply: fc.integer({ min: -50, max: 50 }), spot: fc.integer({ min: -300, max: 300 }) }),
  flipRoutes: fc.array(fc.boolean(), { minLength: ROUTES.length, maxLength: ROUTES.length }),
  jobDelay: fc.integer({ min: 0, max: 2 * TICKS_PER_DAY }),
  extraStock: fc.integer({ min: 0, max: 3 }),
  reputation: fc.integer({ min: 0, max: 100 }),
  futureClosure: fc.option(
    fc.record({ offset: fc.integer({ min: 2, max: 3 * TICKS_PER_DAY }), routePick: fc.nat(), durationTicks: fc.integer({ min: 1, max: TICKS_PER_DAY }) }),
    { nil: null },
  ),
});

/** S₂ from S₁: world values outside the live view and hidden plumbing changed; knowledge, the founder, the ledger and agreements untouched. */
function perturbHidden(s: GameState, plan: HiddenPlan): GameState {
  const hidden = hiddenPredicates(s);
  const routesToOpen = new Set<RouteId>();
  const routes = s.routes.map((r, i) => {
    if (!hidden.route(r.id) || !plan.flipRoutes[i % plan.flipRoutes.length]) return r;
    if (r.closure === null) return { ...r, closure: { reason: "POLICE" as const, reopensAt: null } };
    routesToOpen.add(r.id);
    return { ...r, closure: null };
  });
  let scheduledEvents: ScheduledWorldEvent[] = s.scheduledEvents.filter((e) => !(e.kind === "ROUTE_REOPENING" && routesToOpen.has(e.routeId)));
  let nextScheduleSequence = s.counters.nextScheduleSequence + plan.sequenceBump;
  if (plan.futureClosure && s.routes.length > 0) {
    const routeId = s.routes[plan.futureClosure.routePick % s.routes.length]!.id;
    scheduledEvents.push({
      kind: "ROUTE_CLOSURE",
      tick: tick(s.tick + plan.futureClosure.offset),
      sequence: nextScheduleSequence,
      routeId,
      reason: "RIVAL",
      durationTicks: plan.futureClosure.durationTicks,
    });
    nextScheduleSequence += 1;
    scheduledEvents = scheduledEvents.sort((a, b) => a.tick - b.tick || a.sequence - b.sequence);
  }
  const journal = s.eventJournal.slice(s.eventJournal.length - (plan.journalKeep % (s.eventJournal.length + 1)));
  const rng = Object.fromEntries(RNG_STREAMS.map((stream, i) => [stream, seedRng(plan.rngSeeds[i] ?? 1, stream)])) as GameState["rng"];

  return {
    ...s,
    seed: s.seed + (plan.rngSeeds[0] ?? 1),
    rng,
    eventJournal: journal,
    scheduledEvents,
    counters: { ...s.counters, nextScheduleSequence, nextCommandSequence: s.counters.nextCommandSequence + plan.sequenceBump },
    family: hidden.standing ? { ...s.family, reputation: plan.reputation } : s.family,
    productPools: s.productPools.map((p) => (hidden.facility(p.facilityId) ? { ...p, quantity: p.quantity + plan.extraStock } : p)),
    materialPools: s.materialPools.map((p) => (hidden.facility(p.facilityId) ? { ...p, quantity: p.quantity + plan.extraStock } : p)),
    productionJobs: s.productionJobs.map((j) => (hidden.facility(j.facilityId) ? { ...j, completesAt: tick(j.completesAt + plan.jobDelay) } : j)),
    markets: hidden.market
      ? s.markets.map((m) => ({
          ...m,
          demand: Math.max(1, m.demand + plan.marketDelta.demand),
          supply: Math.max(1, m.supply + plan.marketDelta.supply),
          spotPrice: Math.max(1, m.spotPrice + plan.marketDelta.spot) as typeof m.spotPrice,
        }))
      : s.markets,
    suppliers: s.suppliers.map((sup) =>
      hidden.supplier(sup.id)
        ? {
            ...sup,
            stock: sup.stock.map((st) => ({ ...st, available: plan.supplierAvailable, unitPrice: Math.max(1, st.unitPrice + plan.supplierPriceDelta) as typeof st.unitPrice })),
          }
        : sup,
    ),
    buyers: s.buyers.map((b) =>
      hidden.buyer(b.id)
        ? {
            ...b,
            budgetRemaining: plan.budget as typeof b.budgetRemaining,
            wants: b.wants.map((w) => ({ ...w, demandRemaining: plan.demand, unitPrice: Math.max(1, w.unitPrice + plan.wantPriceDelta) as typeof w.unitPrice })),
          }
        : b,
    ),
    contractOffers: s.contractOffers
      .filter((o) => !(hidden.buyer(o.buyerId) && plan.dropOffers))
      .map((o) => (hidden.buyer(o.buyerId) ? { ...o, unitPrice: Math.max(1, o.unitPrice + plan.offerPriceDelta) as typeof o.unitPrice } : o)),
    routes,
  };
}

const NON_LEAK_SEED = 17_301;
/** A fixed, seeded handful of perturbations, applied at every checkpoint. */
const PLANS: readonly HiddenPlan[] = fc.sample(hiddenPlanArb, { seed: NON_LEAK_SEED, numRuns: 3 });

/** A copy of `sim`'s game with its state replaced (a save of the same game, edited). */
function withState(sim: KernelSimulation, state: GameState): KernelSimulation {
  return loadGame({ ...sim.serialize(), state }, setup);
}

function expectNoLeak(sim: KernelSimulation, where: string): void {
  const hashBefore = sim.stateHash();
  const s1 = sim.playerSnapshot();
  expect(sim.stateHash(), `${where}: playerSnapshot() changed the state`).toBe(hashBefore);
  expect(canonicalJson(sim.playerSnapshot()), `${where}: playerSnapshot() isn't a function of the state`).toBe(canonicalJson(s1));
  PLANS.forEach((plan, i) => {
    const twin = withState(sim, renumberIds(perturbHidden(sim.state, plan), plan.ids));
    expectSamePlayerView(twin.playerSnapshot(), s1, `${where} (perturbation ${i})`);
  });
}

// ---------------------------------------------------------------------------
// The evidence: a player-snapshot summary (only what the player can see)
// ---------------------------------------------------------------------------

const pad2 = (n: number): string => String(n).padStart(2, "0");

function describeFounder(f: PlayerFounder): string {
  const w = f.whereabouts;
  const t = f.tired ? " (tired)" : "";
  switch (w.kind) {
    case "PRESENT":
      return `PRESENT at ${w.locationId}${w.busy ? `, busy ${w.busy.activity} until t=${w.busy.until}` : ", free"}${t}`;
    case "TRAVELLING":
      return `TRAVELLING ${w.transport.kind} to ${w.destinationLocationId}, leg ${w.legIndex + 1}/${w.path.length} on ${w.path[w.legIndex]?.routeId ?? "?"} t=${w.legDepartedAt}..${w.legArrivesAt}${t}`;
    case "ON_DELIVERY":
      return `ON_DELIVERY with ${w.vehicleId}${w.atStop ? `, stopped at ${w.atStop.locationId} t=${w.atStop.tick}` : ""}${t}`;
    case "RESTING":
      return `RESTING at ${w.locationId} t=${w.startedAt}..${w.until}`;
  }
}

/** Every Known value in the snapshot (`{ value, learnedAt, source }`), labelled by its path; list items by `id`. */
function knownValues(node: unknown, path: string, out: string[]): void {
  if (Array.isArray(node)) {
    node.forEach((item, i) => {
      const id = typeof item === "object" && item !== null && "id" in item ? String((item as { id: unknown }).id) : String(i);
      knownValues(item, `${path}[${id}]`, out);
    });
    return;
  }
  if (typeof node !== "object" || node === null) return;
  const o = node as Record<string, unknown>;
  const keys = Object.keys(o).sort();
  if (keys.length === 3 && keys[0] === "learnedAt" && keys[1] === "source" && keys[2] === "value") {
    const source = o["source"] as { kind: string; locationId?: string; partyLocationId?: string };
    const where = source.locationId ?? source.partyLocationId;
    out.push(`${path} @t=${String(o["learnedAt"])} ${source.kind}${where ? ` ${where}` : ""}`);
    return;
  }
  for (const key of keys) {
    if (key === "activity" || key === "catchUp" || key === "founder" || key === "clock") continue;
    knownValues(o[key], path === "" ? key : `${path}.${key}`, out);
  }
}

function summarize(label: string, s: PlayerSnapshot): string {
  const d = s.clock.date;
  const lines = [
    `== ${label}`,
    `  t=${s.clock.tick} day ${s.clock.dayIndex} ${d.year}-${pad2(d.month)}-${pad2(d.day)} ${pad2(d.hour)}:${pad2(d.minute)}; here: ${s.here ?? "-"}`,
    `  founder: ${describeFounder(s.founder)}`,
    `  purse: cash ${s.finance.cash}; known net worth ${s.finance.knownNetWorth.amount} as of ${s.finance.knownNetWorth.asOf ?? "-"}; books ${s.finance.books.length} rows`,
    `  deals: ${s.deals.map((x) => `${x.buyerId} ${x.quantity}× ${x.status}`).join(", ") || "none"}`,
    `  activity: ${s.activity.length} items${s.activity.length ? `, last ${s.activity.at(-1)!.kind}` : ""}; catch-up: ${s.catchUp ? `${s.catchUp.locationId} t=${s.catchUp.tick} since ${s.catchUp.sinceTick ?? "-"}, ${s.catchUp.lines.length} lines, ${s.catchUp.news.length} news` : "none"}`,
  ];
  const known: string[] = [];
  knownValues(s, "", known);
  lines.push(`  known (${known.length}):`, ...known.map((k) => `    ${k}`));
  return lines.join("\n");
}

// ---------------------------------------------------------------------------
// The path
// ---------------------------------------------------------------------------

interface Run {
  readonly sim: KernelSimulation;
  /** Full mode: ledger checks every tick; non-leak, no-trap and a summary entry at each checkpoint. */
  readonly full: boolean;
  readonly summary: string[];
  /** Events since the run (or the resumed run) started. */
  readonly events: GameEvent[];
}

function checkpoint(run: Run, label: string): void {
  if (!run.full) return;
  const where = `${label} (t=${run.sim.state.tick})`;
  expectLedgerReconciles(run.sim.state, where);
  expectNoLeak(run.sim, where);
  const copy = loadGame(JSON.parse(JSON.stringify(run.sim.serialize())) as SaveGame, setup);
  expectRestWithinBound(copy, where);
  run.summary.push(summarize(label, run.sim.playerSnapshot()));
}

function step1(run: Run): void {
  run.sim.advance(1);
  run.events.push(...run.sim.takeEvents());
  if (run.full) {
    const where = `t=${run.sim.state.tick}`;
    expectLedgerReconciles(run.sim.state, where);
    expect(run.sim.playerSnapshot().finance.cash, `${where}: the purse is the ledger's cash`).toBe(accountBalances(run.sim.state.ledger.transactions).CASH);
  }
}

function advanceUntil(run: Run, done: (s: GameState) => boolean, maxTicks: number, what: string): void {
  for (let i = 0; i < maxTicks && !done(run.sim.state); i++) step1(run);
  if (!done(run.sim.state)) throw new Error(`Not reached within ${maxTicks} ticks: ${what} (tick ${run.sim.state.tick}, founder ${JSON.stringify(run.sim.state.founder)})`);
}

function dispatch(run: Run, command: Parameters<KernelSimulation["dispatch"]>[0]["command"], what: string): number {
  const applyTick = run.sim.state.tick + 1;
  const result = run.sim.dispatch({ command });
  expectApplied(result, what);
  expect(result.tick, `${what}: applies at once`).toBe(applyTick);
  run.events.push(...run.sim.takeEvents());
  return applyTick;
}

/** Walk on foot (default path) and check the legs and the arrival tick against game-data. */
function walk(run: Run, destination: LocationId, label: string): void {
  const before = run.sim.state;
  expect(isFree(before), `${label}: free to leave`).toBe(true);
  const from = (before.founder.whereabouts as { locationId: LocationId }).locationId;
  const t = dispatch(run, { type: "TRAVEL", destinationLocationId: destination, transport: { kind: "FOOT" }, via: null }, label);
  const w = run.sim.state.founder.whereabouts;
  if (w.kind !== "TRAVELLING") throw new Error(`${label}: expected TRAVELLING, got ${JSON.stringify(w)}`);
  // The path is simple and runs from here to the destination.
  let at = from;
  const seen = new Set<string>([from]);
  for (const leg of w.path) {
    const r = routeById(leg.routeId);
    expect(leg.reversed ? r.toLocationId : r.fromLocationId, `${label}: legs connect`).toBe(at);
    at = leg.reversed ? r.fromLocationId : r.toLocationId;
    expect(seen.has(at), `${label}: a simple path`).toBe(false);
    seen.add(at);
  }
  expect(at, `${label}: the path ends at the destination`).toBe(destination);
  const legTicks = (leg: RouteLeg): number => footTicks(routeById(leg.routeId).durationTicks);
  expect(w).toEqual({
    kind: "TRAVELLING",
    transport: { kind: "FOOT" },
    path: w.path,
    legIndex: 0,
    legDepartedAt: t,
    legArrivesAt: t + legTicks(w.path[0]!),
    destinationLocationId: destination,
  });
  checkpoint(run, `${label}: set out`);
  const arrival = t + w.path.reduce((n, leg) => n + legTicks(leg), 0);
  advanceUntil(run, (s) => s.founder.whereabouts.kind !== "TRAVELLING", 3 * TICKS_PER_DAY, `${label}: arrival`);
  expect(run.sim.state.tick, `${label}: arrives after the foot legs' time`).toBe(arrival);
  expect(run.sim.state.founder.whereabouts).toEqual({ kind: "PRESENT", locationId: destination, busy: null, call: null });
}

/** A timed activity: busy from its apply tick through `apply + duration`, free on that tick's end. */
function busyActivity(run: Run, kind: ActivityKind, command: Parameters<KernelSimulation["dispatch"]>[0]["command"], label: string): number {
  const before = run.sim.state;
  expect(isFree(before), `${label}: free`).toBe(true);
  const at = (before.founder.whereabouts as { locationId: LocationId }).locationId;
  const duration = activityTicks(kind, before, before.tick + 1);
  const t = dispatch(run, command, label);
  expect(run.sim.state.founder.whereabouts, `${label}: busy`).toEqual({ kind: "PRESENT", locationId: at, busy: { activity: kind, until: t + duration }, call: null });
  checkpoint(run, `${label}: busy`);
  return t + duration;
}

function waitFree(run: Run, until: number, label: string): void {
  advanceUntil(run, isFree, TICKS_PER_DAY, `${label}: done`);
  expect(run.sim.state.tick, `${label}: free on the busy end tick`).toBe(until);
}

interface Step {
  readonly name: string;
  readonly run: (run: Run) => void;
}

const PATH: readonly Step[] = [
  {
    name: "asleep at the start",
    run: (run) => {
      expect(run.sim.state.tick).toBe(0);
      expect(run.sim.state.founder.whereabouts).toEqual({ kind: "RESTING", locationId: HOME, startedAt: 0, until: START_WAKE_TICK });
      checkpoint(run, "asleep at the start");
    },
  },
  {
    name: "wake at Hollow Creek",
    run: (run) => {
      advanceUntil(run, isFree, START_WAKE_TICK + 2, "the founder wakes");
      expect(run.sim.state.tick, "wakes on the rest's last tick").toBe(START_WAKE_TICK);
      expect(run.sim.state.founder.whereabouts).toEqual({ kind: "PRESENT", locationId: HOME, busy: null, call: null });
      checkpoint(run, "awake at home");
    },
  },
  {
    name: "walk to the feed store",
    run: (run) => {
      walk(run, SUPPLIER.locationId, "walk to the feed store");
      checkpoint(run, "at the feed store");
    },
  },
  {
    name: "wait for opening hours",
    run: (run) => {
      const loc = SUPPLIER.locationId;
      advanceUntil(run, (s) => isFree(s) && isOpen(loc, s.tick) && isOpen(loc, s.tick + 1), 2 * TICKS_PER_DAY, "the feed store opens");
      expect(run.sim.state.founder.whereabouts).toEqual({ kind: "PRESENT", locationId: loc, busy: null, call: null });
      // Open, so the supplier's offer is the live view: learned here, now.
      const place = run.sim.playerSnapshot().places.find((p) => p.id === loc);
      expect(place?.kind).toBe("SUPPLIER");
      if (place?.kind === "SUPPLIER") {
        expect(place.supplier.offer, "the offer is seen in person").toMatchObject({ learnedAt: run.sim.state.tick, source: { kind: "IN_PERSON", locationId: loc } });
      }
      checkpoint(run, "the feed store is open");
    },
  },
  ...RECIPE.inputsPerCase.map(
    (input): Step => ({
      name: `buy ${input.materialId}`,
      run: (run) => {
        const label = `buy ${input.materialId}`;
        const quantity = input.quantity * PATH_CASES;
        const pool = (s: GameState): number => s.materialPools.find((p) => p.facilityId === HOME_FACILITY.id && p.materialId === input.materialId)?.quantity ?? 0;
        const had = pool(run.sim.state);
        const until = busyActivity(
          run,
          "BUY_MATERIALS",
          { type: "PURCHASE_MATERIALS", supplierId: SUPPLIER.id, materialId: input.materialId, quantity, facilityId: HOME_FACILITY.id },
          label,
        );
        expect(isOpen(SUPPLIER.locationId, run.sim.state.tick), `${label}: during opening hours`).toBe(true);
        expect(pool(run.sim.state), `${label}: at the still`).toBe(had + quantity);
        waitFree(run, until, label);
        checkpoint(run, `${label}: done`);
      },
    }),
  ),
  {
    name: "walk back to the still",
    run: (run) => {
      walk(run, HOME, "walk back to the still");
      checkpoint(run, "back at the still");
    },
  },
  {
    name: "start a batch",
    run: (run) => {
      const until = busyActivity(run, "START_BATCH", { type: "START_PRODUCTION", facilityId: HOME_FACILITY.id, recipeId: RECIPE.id, quantity: PATH_CASES }, "start a batch");
      expect(run.sim.state.productionJobs, "one batch running").toHaveLength(1);
      expect(run.sim.state.productionJobs[0]).toMatchObject({ facilityId: HOME_FACILITY.id, recipeId: RECIPE.id });
      waitFree(run, until, "start a batch");
      checkpoint(run, "the batch is running");
    },
  },
  {
    name: "wait for the batch",
    run: (run) => {
      const job = run.sim.state.productionJobs[0];
      if (!job) throw new Error("no batch running");
      const had = homeCases(run.sim.state);
      advanceUntil(run, (s) => s.productionJobs.length === 0, 4 * TICKS_PER_DAY, "the batch completes");
      expect(run.sim.state.tick, "completes when it said").toBe(job.completesAt);
      expect(homeCases(run.sim.state), "the cases are at the still").toBe(had + PATH_CASES);
      expect(run.sim.state.founder.whereabouts, "waited at the still").toEqual({ kind: "PRESENT", locationId: HOME, busy: null, call: null });
      checkpoint(run, "the batch is done");
    },
  },
  {
    name: "load the truck for a sale on spec",
    run: (run) => {
      expect(truckOf(run.sim.state)).toMatchObject({ parkedAt: HOME, trip: null });
      busyActivity(
        run,
        "LOAD_TRUCK",
        {
          type: "DISPATCH_DELIVERY",
          vehicleId: TRUCK,
          cargo: [{ productId: RECIPE.productId, quality: RECIPE.quality, quantity: PATH_CASES }],
          purpose: { kind: "SALE", buyerId: SALE.buyerId, dealId: null },
          routeId: SALE.route.id,
          driver: { kind: "FOUNDER" },
        },
        "load the truck",
      );
      const delivery = run.sim.state.deliveries.at(-1)!;
      expect(delivery).toMatchObject({ routeId: SALE.route.id, purpose: { kind: "SALE", buyerId: SALE.buyerId, dealId: null } });
      expect(run.sim.state.heldDeals, "on spec: no deal").toEqual([]);
    },
  },
  {
    name: "ride out",
    run: (run) => {
      const w = run.sim.state.founder.whereabouts;
      if (w.kind !== "PRESENT" || w.busy?.activity !== "LOAD_TRUCK") throw new Error(`expected loading, got ${JSON.stringify(w)}`);
      const deliveryId = run.sim.state.deliveries.at(-1)!.id;
      advanceUntil(run, (s) => s.founder.whereabouts.kind !== "PRESENT", TICKS_PER_DAY, "the truck sets out");
      expect(run.sim.state.tick, "leaves when loading ends").toBe(w.busy.until);
      expect(run.sim.state.founder.whereabouts).toEqual({ kind: "ON_DELIVERY", deliveryId, vehicleId: TRUCK, atStop: null });
      expect(truckOf(run.sim.state).trip).toMatchObject({ deliveryId, leg: "OUTBOUND", routeId: SALE.route.id, arrivesAt: w.busy.until + SALE.route.durationTicks });
      checkpoint(run, "riding out");
    },
  },
  {
    name: "at the buyer",
    run: (run) => {
      const trip = truckOf(run.sim.state).trip!;
      advanceUntil(run, (s) => s.founder.whereabouts.kind === "ON_DELIVERY" && s.founder.whereabouts.atStop !== null, TICKS_PER_DAY, "the stop");
      const stopTick = run.sim.state.tick;
      expect(stopTick, "a risk-free route arrives on time").toBe(trip.arrivesAt);
      expect(run.sim.state.founder.whereabouts).toEqual({
        kind: "ON_DELIVERY",
        deliveryId: trip.deliveryId,
        vehicleId: TRUCK,
        atStop: { locationId: SALE.locationId, tick: stopTick },
      });
      // Settled on arrival at the day's quote: at least one case sold.
      const settled = run.events.find((e) => e.type === "SPEC_SALE_SETTLED" && "deliveryId" in e && e.deliveryId === trip.deliveryId);
      expect(settled, "SPEC_SALE_SETTLED").toMatchObject({ buyerId: SALE.buyerId, offered: PATH_CASES });
      expect((settled as { accepted: number }).accepted, "the buyer takes at least one case").toBeGreaterThanOrEqual(1);
      const sale = run.sim.state.ledger.transactions.find((t) => t.idempotencyKey === idempotencyKey("SALE", trip.deliveryId));
      expect(sale, "a SALE posting").toMatchObject({ kind: "SALE", tick: stopTick });
      expect(sale!.entries.length).toBeGreaterThan(0);
      checkpoint(run, "at the buyer (the stop)");
    },
  },
  {
    name: "ride home",
    run: (run) => {
      const w = run.sim.state.founder.whereabouts;
      if (w.kind !== "ON_DELIVERY" || w.atStop === null) throw new Error(`expected riding after the stop, got ${JSON.stringify(w)}`);
      const stopTick = w.atStop.tick;
      const trip = truckOf(run.sim.state).trip!;
      expect(trip).toMatchObject({ leg: "RETURN", arrivesAt: stopTick + SALE.route.durationTicks });
      step1(run);
      // What the founder saw at the stop is kept: an open buyer's wants, learned there.
      const buyer = run.sim.playerSnapshot().places.find((p) => p.id === SALE.locationId);
      if (buyer?.kind !== "BUYER") throw new Error(`${SALE.locationId} isn't a buyer`);
      if (isOpen(SALE.locationId, stopTick)) {
        expect(buyer.buyer.wants, "the buyer's wants, seen at the stop").toMatchObject({ learnedAt: stopTick, source: { kind: "IN_PERSON", locationId: SALE.locationId } });
      }
      checkpoint(run, "riding home");
      advanceUntil(run, (s) => s.founder.whereabouts.kind !== "ON_DELIVERY", TICKS_PER_DAY, "home");
      expect(run.sim.state.tick, "home when the truck is").toBe(trip.arrivesAt);
      expect(run.sim.state.founder.whereabouts).toEqual({ kind: "PRESENT", locationId: HOME, busy: null, call: null });
      expect(truckOf(run.sim.state)).toMatchObject({ parkedAt: HOME, trip: null });
      expect(run.sim.playerSnapshot().deals, "no deals on spec").toEqual([]);
      checkpoint(run, "home");
    },
  },
  {
    name: "sleep",
    run: (run) => {
      const applyTick = run.sim.state.tick + 1;
      const untilTick = oneClickRestUntil(applyTick);
      dispatch(run, { type: "REST", untilTick }, "rest until morning");
      expect(run.sim.state.founder.whereabouts).toEqual({ kind: "RESTING", locationId: HOME, startedAt: applyTick, until: untilTick });
      checkpoint(run, "asleep");
    },
  },
  {
    name: "wake the next morning",
    run: (run) => {
      const w = run.sim.state.founder.whereabouts;
      if (w.kind !== "RESTING") throw new Error(`expected resting, got ${JSON.stringify(w)}`);
      advanceUntil(run, isFree, MAX_REST_TICKS + 2, "the founder wakes");
      expect(run.sim.state.tick, "wakes on the rest's last tick").toBe(w.until);
      expect(run.sim.state.founder.whereabouts).toEqual({ kind: "PRESENT", locationId: HOME, busy: null, call: null });
      checkpoint(run, "awake the next morning");
    },
  },
];

function runSteps(run: Run, from: number, to: number): void {
  for (let i = from; i < to; i++) PATH[i]!.run(run);
}

function freshRun(full: boolean): Run {
  return { sim: newGame(setup), full, summary: [], events: [] };
}

interface FullRun {
  readonly hash: string;
  readonly tick: number;
  readonly state: GameState;
  readonly summary: string;
}

let fullRun: FullRun | null = null;

/** The path with every check on, once; later tests reuse its result. */
function theFullRun(): FullRun {
  if (!fullRun) {
    const run = freshRun(true);
    runSteps(run, 0, PATH.length);
    fullRun = { hash: run.sim.stateHash(), tick: run.sim.state.tick, state: run.sim.state, summary: `${run.summary.join("\n\n")}\n` };
  }
  return fullRun;
}

function fastRun(): KernelSimulation {
  const run = freshRun(false);
  runSteps(run, 0, PATH.length);
  return run.sim;
}

