// The scenario
// ---------------------------------------------------------------------------

describe("the M002 scenario (THE_FIRST_HIRE_SCENARIO)", () => {
  it("is a separate scenario with the founder's rules on, at M002's slower pacing, starting at Hollow Creek", () => {
    expect(SCENARIO.id).not.toBe(FIRST_SHIPMENT_SCENARIO.id);
    expect(SCENARIO.founderRules).toBe(true);
    expect(SCENARIO.realMsPerGameHourAt1x).toBeGreaterThan(FIRST_SHIPMENT_SCENARIO.realMsPerGameHourAt1x);
    expect(SCENARIO.founderStartLocationId).toBe(HOLLOW_CREEK);
    // The M001 scenario is unaffected.
    expect(FIRST_SHIPMENT_SCENARIO.founderRules).toBe(false);
  });

  it("has what the path needs: the still at home with basic moonshine's equipment, the truck, a supplier and a buyer", () => {
    for (const equipmentId of RECIPE.requiredEquipmentIds) expect(HOME_FACILITY.equipmentIds).toContain(equipmentId);
    expect(SCENARIO.supplierIds).toContain(SUPPLIER.id);
    expect(SCENARIO.buyerIds).toContain(SALE.buyerId);
    expect(SALE.route.riskPpm).toBe(0);
    const sim = newGame(setup);
    expect(truckOf(sim.state)).toMatchObject({ parkedAt: HOME, trip: null });
  });

  it("starts the founder alone and asleep at home, with no phone of their own", () => {
    const sim = newGame(setup);
    expect(sim.state.scenarioId).toBe(SCENARIO.id);
    expect(sim.state.founder.whereabouts).toEqual({ kind: "RESTING", locationId: HOME, startedAt: 0, until: START_WAKE_TICK });
    expect(sim.state.facilities.map((f) => f.phoneLine), "no family phone line").toEqual(sim.state.facilities.map(() => null));
    const home: PlayerPlace | undefined = sim.playerSnapshot().places.find((p) => p.id === HOME);
    expect(home?.phone, "no phone at home").toBeNull();
    expect(sim.state.heldDeals).toEqual([]);
    expect(sim.state.contracts).toEqual([]);
  });

  it("opens with enough cash for the batch's materials, its conversion cost and the trip", () => {
    const sim = newGame(setup);
    const supplier = sim.state.suppliers.find((s) => s.id === SUPPLIER.id)!;
    const materials = RECIPE.inputsPerCase.reduce((n, i) => n + supplier.stock.find((st) => st.materialId === i.materialId)!.unitPrice * i.quantity * PATH_CASES, 0);
    const conversion = (RECIPE.laborPerCase + RECIPE.overheadPerCase) * PATH_CASES;
    const cash = accountBalances(sim.state.ledger.transactions).CASH;
    expect(cash).toBe(SCENARIO.openingBalance.cash);
    expect(cash).toBeGreaterThanOrEqual(materials + conversion + SALE.route.transportCost);
    expectLedgerReconciles(sim.state, "opening");
  });
});

// ---------------------------------------------------------------------------
// The path
// ---------------------------------------------------------------------------

describe("the M002 walking skeleton (SK1d)", () => {
  it(
    "runs wake → feed store → buy → still → batch → on-spec sale, riding → home → sleep, every step accepted, with the ledger reconciled every tick and no leak or trap at any checkpoint",
    { timeout: 60_000 },
    () => {
      const run = theFullRun();
      expect(run.state.outcome).toEqual({ status: "PLAYING" });
      expect(run.state.queuedCommands).toEqual([]);
      expect(run.state.heldDeals).toEqual([]);
      expect(run.state.productionJobs).toEqual([]);
      expect(run.state.founder.whereabouts).toEqual({ kind: "PRESENT", locationId: HOME, busy: null, call: null });
      // TRAVEL, the purchases, START_PRODUCTION, DISPATCH_DELIVERY, TRAVEL, REST: each applied once.
      expect(run.state.commandLog.map((e) => e.command.type)).toEqual([
        "TRAVEL",
        ...RECIPE.inputsPerCase.map(() => "PURCHASE_MATERIALS"),
        "TRAVEL",
        "START_PRODUCTION",
        "DISPATCH_DELIVERY",
        "REST",
      ]);
    },
  );

  it("produces the path's player-snapshot summary (evidence: walking-skeleton/path-summary.txt)", { timeout: 60_000 }, async () => {
    const { summary } = theFullRun();
    for (const step of ["asleep at the start", "at the feed store", "at the buyer (the stop)", "home", "asleep", "awake the next morning"]) {
      expect(summary).toContain(`== ${step}\n`);
    }
    await expect(summary).toMatchFileSnapshot("./path-summary.txt");
  });
});

// ---------------------------------------------------------------------------
// Determinism
// ---------------------------------------------------------------------------

describe("the walking skeleton is deterministic", () => {
  it("the same path gives the same hash, with or without the checks", { timeout: 60_000 }, () => {
    const a = fastRun();
    const b = fastRun();
    expect(b.stateHash()).toBe(a.stateHash());
    expect(a.stateHash(), "the checks (snapshots, copies) changed nothing").toBe(theFullRun().hash);
  });

  it("equals the pinned M002 reference hash", { timeout: 60_000 }, () => {
    expect(WALKING_SKELETON_HASH).toMatch(/^fnv1a64:[0-9a-f]{16}$/);
    expect(theFullRun().hash).toBe(WALKING_SKELETON_HASH);
  });

  it("replaying the command log on a fresh game reproduces the final hash and the log", { timeout: 60_000 }, () => {
    const original = theFullRun();
    const log = original.state.commandLog;
    const replayed = newGame(setup);
    for (const envelope of log.filter((e) => e.scheduledTick <= original.tick)) {
      const gap = envelope.scheduledTick - 1 - replayed.state.tick;
      if (gap > 0) replayed.advance(gap);
      const result = replayed.replay(envelope);
      expect(result.status, `replay ${envelope.id} (${envelope.command.type})`).not.toBe("rejected");
      expect(result.status, `replay ${envelope.id} (${envelope.command.type})`).not.toBe("rejected-on-apply");
    }
    replayed.advance(original.tick - replayed.state.tick);
    for (const envelope of log.filter((e) => e.scheduledTick > original.tick)) expect(replayed.replay(envelope).status).not.toBe("rejected");
    expect(replayed.state.tick).toBe(original.tick);
    expect(replayed.state.commandLog).toEqual(log);
    expect(replayed.stateHash()).toBe(original.hash);
  });

  it("save → load → continue at every step boundary reaches the uninterrupted run's final hash", { timeout: 60_000 }, () => {
    const expected = theFullRun().hash;
    for (let split = 1; split < PATH.length; split++) {
      const first = freshRun(false);
      runSteps(first, 0, split);
      const save = JSON.parse(JSON.stringify(first.sim.serialize())) as SaveGame;
      expect(save.format).toBe(SAVE_FORMAT);
      expect(hashState(save.state), `split before "${PATH[split]!.name}": the save hashes as the state`).toBe(first.sim.stateHash());
      const resumed: Run = { sim: loadGame(save, setup), full: false, summary: [], events: [] };
      expect(resumed.sim.stateHash(), `split before "${PATH[split]!.name}": loads as saved`).toBe(first.sim.stateHash());
      runSteps(resumed, split, PATH.length);
      expect(resumed.sim.stateHash(), `split before "${PATH[split]!.name}"`).toBe(expected);
    }
  });
});
